package com.haucheng.erp.service;
import com.haucheng.erp.dto.UnitRequest; import com.haucheng.erp.entity.MdUnit; import com.haucheng.erp.exception.BusinessException; import com.haucheng.erp.mapper.UnitMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service @RequiredArgsConstructor public class UnitService { private final UnitMapper mapper; private final OperationLogService operationLog;
 public List<MdUnit> getAll(){return mapper.selectAll();} public List<MdUnit> getOptions(){return mapper.selectAll().stream().filter(x->Boolean.TRUE.equals(x.getStatus())).toList();} public MdUnit getById(Long id){MdUnit e=require(id);return e;}
 @Transactional public MdUnit create(UnitRequest r){String c=r.getUnitCode().trim(),n=r.getUnitName().trim();unique(c,n,null);MdUnit e=build(r,c,n);mapper.insert(e);operationLog.record("UNIT_CREATE",String.valueOf(e.getId()),"创建单位");return e;}
 @Transactional public MdUnit update(Long id,UnitRequest r){require(id);String c=r.getUnitCode().trim(),n=r.getUnitName().trim();unique(c,n,id);MdUnit e=build(r,c,n);e.setId(id);mapper.update(e);operationLog.record("UNIT_UPDATE",String.valueOf(id),"修改单位");return e;}
 @Transactional public void updateStatus(Long id,Boolean status){MdUnit e=require(id);e.setStatus(status);mapper.update(e);operationLog.record(status?"UNIT_ENABLE":"UNIT_DISABLE",String.valueOf(id),status?"启用单位":"停用单位");}
 @Transactional public void delete(Long id){require(id);if(mapper.countProducts(id)>0)throw BusinessException.conflict("单位已被物资使用，不能删除");mapper.deleteById(id);operationLog.record("UNIT_DELETE",String.valueOf(id),"删除单位");}
 private MdUnit require(Long id){MdUnit e=mapper.selectById(id);if(e==null)throw BusinessException.notFound("单位不存在");return e;} private void unique(String c,String n,Long id){if(mapper.countByCode(c,id)>0)throw BusinessException.conflict("单位编号已存在");if(mapper.countByName(n,id)>0)throw BusinessException.conflict("单位名称已存在");} private MdUnit build(UnitRequest r,String c,String n){MdUnit e=new MdUnit();e.setUnitCode(c);e.setUnitName(n);e.setPrecisionScale(r.getPrecisionScale());e.setStatus(r.getStatus()==null||r.getStatus());return e;}
}
